use axum::{routing::get, Json, Router}; use serde::Serialize; use tower_http::cors::CorsLayer;
#[derive(Serialize)]struct Market{symbol:&'static str,name:&'static str,unit:&'static str,m:u64,cap:u64,status:&'static str,expiry:&'static str,description:&'static str}
async fn markets()->Json<Vec<Market>>{Json(vec![Market{symbol:"MILK",name:"US Class III Milk",unit:"USD/cwt",m:2000,cap:25,status:"live demo",expiry:"2026-10",description:"USDA announced Class III price; one full contract = 2,000 cwt / 200,000 lb"},Market{symbol:"POTATO",name:"RawMarket US Russet Potato Index v1",unit:"USD / 50 lb carton",m:1,cap:35,status:"historical/demo",expiry:"2026-10",description:"Russet Norkotah, U.S. One, 70-count, 50 lb cartons"},Market{symbol:"TOMATO",name:"RawMarket US Round Tomato Index v1",unit:"USD / 25 lb carton",m:1,cap:40,status:"historical/demo",expiry:"2026-10",description:"Round mature-green, 85% U.S. One or better, 5x6, 25 lb cartons"},Market{symbol:"WHEAT",name:"RawMarket US Wheat Index v1",unit:"USD / bushel",m:1,cap:15,status:"historical/demo",expiry:"2026-10",description:"US domestic cash benchmark; coverage audit required before issuance"},Market{symbol:"CORN",name:"RawMarket US Corn Index v1",unit:"USD / bushel",m:1,cap:10,status:"historical/demo",expiry:"2026-10",description:"US domestic cash benchmark; coverage audit required before issuance"},Market{symbol:"RICE",name:"RawMarket US Rice Index v1",unit:"USD / cwt",m:1,cap:30,status:"historical/demo",expiry:"2026-10",description:"US long-grain benchmark; coverage audit required before issuance"},Market{symbol:"SOYBEAN",name:"RawMarket US Soybean Index v1",unit:"USD / bushel",m:1,cap:25,status:"historical/demo",expiry:"2026-10",description:"US domestic cash benchmark; coverage audit required before issuance"},Market{symbol:"DRY_BEAN",name:"RawMarket US Dry Bean Index v1",unit:"USD / cwt",m:1,cap:80,status:"historical/demo",expiry:"2026-10",description:"US dry edible bean benchmark; coverage audit required before issuance"}])}
async fn health()->&'static str{"ok"} #[tokio::main]async fn main(){let app=Router::new().route("/api/markets",get(markets)).route("/health",get(health)).layer(CorsLayer::permissive());let listener=tokio::net::TcpListener::bind("0.0.0.0:8080").await.unwrap();println!("RawMarket engine on http://localhost:8080");axum::serve(listener,app).await.unwrap();}
